using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using dotnetapp.Models; using Microsoft.AspNetCore.Identity; using Microsoft.IdentityModel.Tokens;
namespace dotnetapp.Services;
public class AuthService(UserManager<ApplicationUser> users,RoleManager<IdentityRole> roles,IConfiguration config):IAuthService {
 public async Task<(int,string)> Registration(User m,string role){if(await users.FindByEmailAsync(m.Email)!=null)return(400,"User already exists"); if(role is not (UserRoles.Baker or UserRoles.Customer))return(400,"Invalid role"); if(!await roles.RoleExistsAsync(role))await roles.CreateAsync(new IdentityRole(role)); var u=new ApplicationUser{Name=m.Username,UserName=m.Email,Email=m.Email,PhoneNumber=m.MobileNumber,UserRole=role}; var r=await users.CreateAsync(u,m.Password); if(!r.Succeeded)return(400,string.Join("; ",r.Errors.Select(e=>e.Description)));await users.AddToRoleAsync(u,role);return(200,"User created successfully!");}
 public async Task<(int,object)> Login(LoginModel m){var u=await users.FindByEmailAsync(m.Email);if(u==null)return(400,new{message="Invalid email"});if(!await users.CheckPasswordAsync(u,m.Password))return(400,new{message="Invalid password"});var rs=await users.GetRolesAsync(u);var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,u.Id),new(JwtRegisteredClaimNames.Email,u.Email!),new(ClaimTypes.Name,u.Name)};claims.AddRange(rs.Select(r=>new Claim(ClaimTypes.Role,r)));return(200,new{Status="Success",token=GenerateToken(claims),username=u.Name,role=rs.FirstOrDefault()});}
 string GenerateToken(IEnumerable<Claim> claims){var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["JWT:Secret"]??throw new InvalidOperationException("JWT secret missing")));return new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(config["JWT:ValidIssuer"],config["JWT:ValidAudience"],claims,expires:DateTime.UtcNow.AddHours(3),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256)));}
}
